370:static void alloc_tile_list_buffer(AV1Decoder *pbi) {
371:  // The resolution of the output frame is read out from the bitstream. The data
372:  // are stored in the order of Y plane, U plane and V plane. As an example, for
373:  // image format 4:2:0, the output frame of U plane and V plane is 1/4 of the
374:  // output frame.
375:  AV1_COMMON *const cm = &pbi->common;
376:  int tile_width, tile_height;
377:  av1_get_uniform_tile_size(cm, &tile_width, &tile_height);
378:  const int tile_width_in_pixels = tile_width * MI_SIZE;
379:  const int tile_height_in_pixels = tile_height * MI_SIZE;
380:  const int output_frame_width =
381:      (pbi->output_frame_width_in_tiles_minus_1 + 1) * tile_width_in_pixels;
382:  const int output_frame_height =
383:      (pbi->output_frame_height_in_tiles_minus_1 + 1) * tile_height_in_pixels;
384:  // The output frame is used to store the decoded tile list. The decoded tile
385:  // list has to fit into 1 output frame.
386:  assert((pbi->tile_count_minus_1 + 1) <=
387:         (pbi->output_frame_width_in_tiles_minus_1 + 1) *
388:             (pbi->output_frame_height_in_tiles_minus_1 + 1));
389:
390:  // Allocate the tile list output buffer.
391:  // Note: if cm->seq_params.use_highbitdepth is 1 and cm->seq_params.bit_depth
392:  // is 8, we could allocate less memory, namely, 8 bits/pixel.
393:  if (aom_alloc_frame_buffer(&pbi->tile_list_outbuf, output_frame_width,
394:                             output_frame_height, cm->seq_params.subsampling_x,
395:                             cm->seq_params.subsampling_y,
396:                             (cm->seq_params.use_highbitdepth &&
397:                              (cm->seq_params.bit_depth > AOM_BITS_8)),
398:                             0, cm->features.byte_alignment))
399:    aom_internal_error(&cm->error, AOM_CODEC_MEM_ERROR,
400:                       "Failed to allocate the tile list output buffer");
401:}
402:
403:static void yv12_tile_copy(const YV12_BUFFER_CONFIG *src, int hstart1,
404:                           int hend1, int vstart1, int vend1,
405:                           YV12_BUFFER_CONFIG *dst, int hstart2, int vstart2,
406:                           int plane) {
407:  const int src_stride = (plane > 0) ? src->strides[1] : src->strides[0];
408:  const int dst_stride = (plane > 0) ? dst->strides[1] : dst->strides[0];
409:  int row, col;
410:
411:  assert(src->flags & YV12_FLAG_HIGHBITDEPTH);
412:  assert(!(dst->flags & YV12_FLAG_HIGHBITDEPTH));
413:
414:  const uint16_t *src16 =
415:      CONVERT_TO_SHORTPTR(src->buffers[plane] + vstart1 * src_stride + hstart1);
416:  uint8_t *dst8 = dst->buffers[plane] + vstart2 * dst_stride + hstart2;
417:
418:  for (row = vstart1; row < vend1; ++row) {
419:    for (col = 0; col < (hend1 - hstart1); ++col) *dst8++ = (uint8_t)(*src16++);
420:    src16 += src_stride - (hend1 - hstart1);
421:    dst8 += dst_stride - (hend1 - hstart1);
422:  }
423:  return;
424:}
425:
426:static void copy_decoded_tile_to_tile_list_buffer(AV1Decoder *pbi,
427:                                                  int tile_idx) {
428:  AV1_COMMON *const cm = &pbi->common;
429:  int tile_width, tile_height;
430:  av1_get_uniform_tile_size(cm, &tile_width, &tile_height);
431:  const int tile_width_in_pixels = tile_width * MI_SIZE;
432:  const int tile_height_in_pixels = tile_height * MI_SIZE;
433:  const int ssy = cm->seq_params.subsampling_y;
434:  const int ssx = cm->seq_params.subsampling_x;
435:  const int num_planes = av1_num_planes(cm);
436:
437:  YV12_BUFFER_CONFIG *cur_frame = &cm->cur_frame->buf;
438:  const int tr = tile_idx / (pbi->output_frame_width_in_tiles_minus_1 + 1);
439:  const int tc = tile_idx % (pbi->output_frame_width_in_tiles_minus_1 + 1);
440:  int plane;
441:
442:  // Copy decoded tile to the tile list output buffer.
443:  for (plane = 0; plane < num_planes; ++plane) {
444:    const int shift_x = plane > 0 ? ssx : 0;
445:    const int shift_y = plane > 0 ? ssy : 0;
446:    const int h = tile_height_in_pixels >> shift_y;
447:    const int w = tile_width_in_pixels >> shift_x;
448:
449:    // src offset
450:    int vstart1 = pbi->dec_tile_row * h;
451:    int vend1 = vstart1 + h;
452:    int hstart1 = pbi->dec_tile_col * w;
453:    int hend1 = hstart1 + w;
454:    // dst offset
455:    int vstart2 = tr * h;
456:    int hstart2 = tc * w;
457:
458:    if (cm->seq_params.use_highbitdepth &&
459:        cm->seq_params.bit_depth == AOM_BITS_8) {
460:      yv12_tile_copy(cur_frame, hstart1, hend1, vstart1, vend1,
461:                     &pbi->tile_list_outbuf, hstart2, vstart2, plane);
462:    } else {
463:      switch (plane) {
464:        case 0:
465:          aom_yv12_partial_copy_y(cur_frame, hstart1, hend1, vstart1, vend1,
466:                                  &pbi->tile_list_outbuf, hstart2, vstart2);
467:          break;
468:        case 1:
469:          aom_yv12_partial_copy_u(cur_frame, hstart1, hend1, vstart1, vend1,
470:                                  &pbi->tile_list_outbuf, hstart2, vstart2);
471:          break;
472:        case 2:
473:          aom_yv12_partial_copy_v(cur_frame, hstart1, hend1, vstart1, vend1,
474:                                  &pbi->tile_list_outbuf, hstart2, vstart2);
475:          break;
476:        default: assert(0);
477:      }
478:    }
479:  }
480:}
